import { sameQualifiedName } from "./automatic-aliases.js";
import { parseGrammar } from "./grammar.js";
import { resolveGrammar } from "./resolution.js";
import { sourceLines, tokenizeSimpleStateForm } from "./source.js";
/** Enumerate exact structural, explicit-alias, and evidenced-alias spellings. */
export function ownedTypeNameSpellings(inventory) {
    return inventory.ownedTypeNames;
}
/** The subset whose identifier a type name spells, in either number: `VerifiedUser` or `VerifiedUsers`. */
export function subsetIdentifiedBy(inventory, typeName) {
    return inventory.subsets.find(({ identifiers, qualifierPrefix }) => identifiers.some((identifier) => sameQualifiedName(qualifierPrefix, identifier, typeName)));
}
/** Parse and validate the bounded structural SSF grammar. */
export function parseSimpleStateForm(source, options = {}) {
    const tokens = tokenizeSimpleStateForm(source);
    return resolveGrammar(parseGrammar(sourceLines(source, tokens)), options);
}
/** Return deterministic, source-located SSF diagnostics. */
export function validateSimpleStateForm(source, options = {}) {
    return parseSimpleStateForm(source, options).diagnostics;
}
